/**
 * Tiny, dependency-free, safe Markdown → HTML renderer.
 *
 * Deliberately minimal: it supports the subset used by our internal docs
 * (headings, bold/italic, inline code, fenced/indented code blocks, unordered &
 * ordered lists, blockquotes, links, horizontal rules, paragraphs). It is NOT a
 * general CommonMark implementation.
 *
 * Safety: ALL raw text is HTML-escaped before any markup is emitted, so the
 * rendered document can never inject markup or scripts from the source file.
 * Link targets are whitelisted to http(s)/mailto/relative/anchor URLs; anything
 * else (e.g. javascript:) is dropped and rendered as plain text.
 */

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function safeUrl(url: string): string | null {
  const u = url.trim();
  if (/^(https?:\/\/|mailto:)/i.test(u)) return u;
  if (u.startsWith("/") || u.startsWith("#")) return u;
  return null;
}

/** Inline formatting on a single (already block-stripped) line of raw text. */
function renderInline(raw: string): string {
  // Pull out inline code first so ** / * / [] inside code stay literal.
  const codes: string[] = [];
  let text = raw.replace(/`([^`]+)`/g, (_m, code) => {
    codes.push(`<code class="rounded bg-white/[0.07] px-1.5 py-0.5 text-[0.85em] text-brand-200">${escapeHtml(code)}</code>`);
    return `�${codes.length - 1}�`;
  });

  text = escapeHtml(text);

  // Links: [label](url) — escapeHtml already ran, so brackets/parens are intact.
  text = text.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (m, label, url) => {
    const href = safeUrl(url);
    if (!href) return label;
    return `<a href="${escapeHtml(href)}" class="text-brand-300 underline decoration-brand-500/40 underline-offset-2 hover:text-brand-200" target="_blank" rel="noreferrer">${label}</a>`;
  });

  text = text.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
  text = text.replace(/(^|[^*])\*([^*]+)\*/g, "$1<em>$2</em>");
  text = text.replace(/(^|[^_])_([^_]+)_/g, "$1<em>$2</em>");

  // Restore code placeholders.
  text = text.replace(/�(\d+)�/g, (_m, i) => codes[Number(i)]);
  return text;
}

/** Render Markdown source to a sanitized HTML string. */
export function renderMarkdown(src: string): string {
  const lines = src.replace(/\r\n/g, "\n").split("\n");
  const out: string[] = [];
  let i = 0;

  const flushList = (items: string[], ordered: boolean) => {
    if (items.length === 0) return;
    const tag = ordered ? "ol" : "ul";
    const cls = ordered ? "ml-5 list-decimal space-y-1" : "ml-5 list-disc space-y-1";
    out.push(`<${tag} class="${cls} text-slate-300">${items.map((it) => `<li>${renderInline(it)}</li>`).join("")}</${tag}>`);
  };

  while (i < lines.length) {
    const line = lines[i];

    // Fenced code block.
    const fence = line.match(/^```(.*)$/);
    if (fence) {
      const body: string[] = [];
      i++;
      while (i < lines.length && !/^```/.test(lines[i])) {
        body.push(lines[i]);
        i++;
      }
      i++; // consume closing fence
      out.push(
        `<pre class="overflow-x-auto rounded-xl border border-white/[0.07] bg-navy-950/70 p-4 text-[13px] leading-relaxed text-slate-200"><code>${escapeHtml(body.join("\n"))}</code></pre>`
      );
      continue;
    }

    // Blank line.
    if (line.trim() === "") {
      i++;
      continue;
    }

    // Horizontal rule.
    if (/^(-{3,}|\*{3,}|_{3,})$/.test(line.trim())) {
      out.push('<hr class="my-6 border-white/[0.08]" />');
      i++;
      continue;
    }

    // Heading.
    const h = line.match(/^(#{1,6})\s+(.*)$/);
    if (h) {
      const level = h[1].length;
      const sizes: Record<number, string> = {
        1: "mt-2 text-2xl font-bold tracking-tight text-white",
        2: "mt-8 text-xl font-bold tracking-tight text-white",
        3: "mt-6 text-lg font-semibold text-white",
        4: "mt-5 text-base font-semibold text-slate-100",
        5: "mt-4 text-sm font-semibold text-slate-200",
        6: "mt-4 text-sm font-semibold text-slate-300",
      };
      out.push(`<h${level} class="${sizes[level] ?? sizes[6]}">${renderInline(h[2])}</h${level}>`);
      i++;
      continue;
    }

    // Blockquote.
    if (/^>\s?/.test(line)) {
      const body: string[] = [];
      while (i < lines.length && /^>\s?/.test(lines[i])) {
        body.push(lines[i].replace(/^>\s?/, ""));
        i++;
      }
      out.push(`<blockquote class="border-l-2 border-brand-500/50 pl-4 text-slate-400">${renderInline(body.join(" "))}</blockquote>`);
      continue;
    }

    // Unordered list.
    if (/^\s*[-*+]\s+/.test(line)) {
      const items: string[] = [];
      while (i < lines.length && /^\s*[-*+]\s+/.test(lines[i])) {
        items.push(lines[i].replace(/^\s*[-*+]\s+/, ""));
        i++;
      }
      flushList(items, false);
      continue;
    }

    // Ordered list.
    if (/^\s*\d+\.\s+/.test(line)) {
      const items: string[] = [];
      while (i < lines.length && /^\s*\d+\.\s+/.test(lines[i])) {
        items.push(lines[i].replace(/^\s*\d+\.\s+/, ""));
        i++;
      }
      flushList(items, true);
      continue;
    }

    // GitHub-style table: a header row, a `| --- | :--: |` delimiter row, then
    // body rows. Without this the delimiter row and every cell collapse into the
    // paragraph fallback and the reader gets a run-on line of pipe characters —
    // which is exactly how every table in DOCUMENTATION.md rendered at
    // /admin/docs until this was added. Alignment markers are honoured.
    if (/^\s*\|/.test(line) && i + 1 < lines.length && /^\s*\|?[\s:|-]*-[\s:|-]*\|?\s*$/.test(lines[i + 1]) && lines[i + 1].includes("-")) {
      const cells = (row: string) =>
        row.trim().replace(/^\||\|$/g, "").split("|").map((c) => c.trim());
      const headers = cells(line);
      const aligns = cells(lines[i + 1]).map((c) =>
        /^:-+:$/.test(c) ? "center" : /^-+:$/.test(c) ? "right" : "left"
      );
      i += 2;
      const rows: string[][] = [];
      while (i < lines.length && /^\s*\|/.test(lines[i]) && lines[i].trim() !== "") {
        rows.push(cells(lines[i]));
        i++;
      }
      const align = (n: number) => `text-${aligns[n] ?? "left"}`;
      const head = headers
        .map((hCell, n) => `<th class="border-b border-white/[0.12] px-3 py-2 font-semibold text-white ${align(n)}">${renderInline(hCell)}</th>`)
        .join("");
      const body = rows
        .map(
          (r) =>
            `<tr class="border-b border-white/[0.06] last:border-0">${headers
              .map((_h, n) => `<td class="px-3 py-2 align-top text-slate-300 ${align(n)}">${renderInline(r[n] ?? "")}</td>`)
              .join("")}</tr>`
        )
        .join("");
      out.push(
        `<div class="my-4 overflow-x-auto rounded-xl border border-white/[0.07]">` +
          `<table class="w-full border-collapse text-left text-[13px]">` +
          `<thead><tr>${head}</tr></thead><tbody>${body}</tbody></table></div>`
      );
      continue;
    }

    // Paragraph: gather consecutive non-blank, non-structural lines.
    const para: string[] = [];
    while (
      i < lines.length &&
      lines[i].trim() !== "" &&
      !/^```/.test(lines[i]) &&
      !/^(#{1,6})\s/.test(lines[i]) &&
      !/^>\s?/.test(lines[i]) &&
      !/^\s*[-*+]\s+/.test(lines[i]) &&
      !/^\s*\d+\.\s+/.test(lines[i]) &&
      !/^(-{3,}|\*{3,}|_{3,})$/.test(lines[i].trim())
    ) {
      para.push(lines[i]);
      i++;
    }
    out.push(`<p class="leading-relaxed text-slate-300">${renderInline(para.join(" "))}</p>`);
  }

  return out.join("\n");
}

import { promises as fs } from "fs";
import path from "path";
import { requireArea } from "@/lib/rbac";
import { PageHeader, Badge } from "@/components/ui/primitives";
import { renderMarkdown } from "@/lib/markdown";
import { DocsViewer, type DocSection } from "@/components/admin/DocsViewer";

export const dynamic = "force-dynamic";

/**
 * Private, admin-only view of the platform documentation. Reads
 * docs/DOCUMENTATION.md straight off disk (server-side) and renders it with a
 * small in-house safe Markdown renderer — the public /docs page is retired.
 */
export default async function AdminDocs() {
  await requireArea("platform");

  let raw = "";
  let error: string | null = null;
  try {
    raw = await fs.readFile(path.join(process.cwd(), "docs", "DOCUMENTATION.md"), "utf8");
  } catch {
    error = "docs/DOCUMENTATION.md could not be read from disk.";
  }

  // Split into searchable sections at each H2 heading; everything before the
  // first H2 is the intro section.
  const sections: DocSection[] = [];
  if (raw) {
    const lines = raw.replace(/\r\n/g, "\n").split("\n");
    let title = "Overview";
    let buf: string[] = [];
    let idx = 0;
    const push = () => {
      const body = buf.join("\n").trim();
      if (!body && sections.length > 0) return;
      sections.push({
        id: `sec-${idx++}`,
        title,
        html: renderMarkdown(body),
        search: `${title}\n${body}`.toLowerCase(),
      });
    };
    for (const line of lines) {
      const h2 = line.match(/^##\s+(.*)$/);
      if (h2) {
        push();
        buf = [line];
        title = h2[1].trim();
      } else {
        buf.push(line);
      }
    }
    push();
  }

  return (
    <div className="space-y-6">
      <PageHeader title="Documentation" sub="Internal platform documentation — private to staff.">
        <Badge tone="brand">{sections.length} sections</Badge>
      </PageHeader>

      {error ? (
        <div className="card py-12 text-center text-sm text-red-300">{error}</div>
      ) : (
        <DocsViewer sections={sections} />
      )}
    </div>
  );
}

